css:
.ac-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #e8f4fa; }
.ac-stage canvas { touch-action: none; cursor: pointer; user-select: none; -webkit-user-select: none; }
.ac-calc { border: 2px solid var(--ink); border-radius: 12px; background: #fff; padding: 14px 18px; flex: none; }
.ac-eq { font: 700 22px/1.5 var(--f-body); color: var(--ink); }
.ac-num { font: 600 24px/1.6 var(--f-body); margin-top: 6px; min-height: 3.2em; white-space: nowrap; }
.ac-num .v { font-weight: 800; color: #1f4fa0; }
.ac-num b.up { color: #c4520f; font-size: 30px; }
.ac-num b.dn { color: #7a34bf; font-size: 30px; }
.ac-recs { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; flex: none; }
.ac-rec { border: 2px dashed var(--ink-3); border-radius: 12px; padding: 10px 14px; background: color-mix(in srgb, var(--ink) 3%, transparent); }
.ac-rec > b { font: 800 22px var(--f-body); }
.ac-rec[data-k="gas"] > b { color: #c4520f; }
.ac-rec[data-k="brake"] > b { color: #7a34bf; }
.ac-rec.on { border-style: solid; background: #fff; }
.ac-rec[data-k="gas"].on { border-color: #ef6a1a; }
.ac-rec[data-k="brake"].on { border-color: #8a3fd1; }
.ac-rv { margin: 4px 0 0; font-size: 20px; line-height: 1.5; color: var(--ink-2); }
.ac-big { font-weight: 800; font-size: 26px; color: var(--ink); white-space: nowrap; }
.ac-dir { font-weight: 800; white-space: nowrap; }
.ac-recs.cmp .ac-dir { background: color-mix(in srgb, var(--hl) 70%, #fff); border-radius: 6px; padding: 0 4px; }
.ac-out { margin: 0; font-size: 22px; line-height: 1.55; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 12px 16px; }

